'use strict';
const batchMetrics=['n','mean','median','sd','p50','p75','p90','p95','min','max'];
const bt=(code,params=[])=>wt('batch.'+code,params);
const batchReason=i=>bt(typeof i==='string'?i:i.code,(i.params||[]).map(v=>typeof v==='number'?v.toLocaleString(I18n.numberLocale,{maximumFractionDigits:6}):v));
const batchClock=clock=>clock==='instant'?'UTC':clock==='wall'?bt('wallClock'):'—';
const batchLabel=g=>[g.product,g.equipment,g.step||g.batch].filter(Boolean).join(' / ')+(g.clock?' · '+batchClock(g.clock):'');
function batchValue(value,key='duration',s=wfState('batch').settings){return typeof value==='number'&&Number.isFinite(value)?key==='n'||key==='excluded'?value:value/(s.displayUnit==='hour'?60:1):null;}
function batchMetricName(k){return k.startsWith('p')&&/^p\d/.test(k)?k.toUpperCase():wt(k);}
function batchStamp(ms,clock){return Number.isFinite(ms)?new Date(ms).toISOString().replace(clock==='wall'?'Z':/$^/,'').replace('.000',''):'';}
function batchSampleSources(){const headers=['Batch ID','Product','Equipment','Process Step','Start Time','End Time','Delay Category','Delay Reason','Target Time','Loss Type'];const rows=[];for(let month=8;month<10;month++)for(let n=0;n<12;n++){const start=Date.UTC(2026,month,1+n,8),slow=month===8?1.3:1;const steps=[['Charging',0,90,'Reactor-1',90,''],['Heating',100,120*slow+(n%3)*10,'Reactor-1',120,''],['Reaction',270,420*slow+(n===10?400:0),'Reactor-1',420,''],['Sampling',310,25,'Lab-1',30,''],['Transfer',1000,75,'Transfer-1',70,''],['Waiting',1100,n===10?90:20,'Transfer-1',0,'waiting']];for(const [step,offset,duration,equipment,target,lossType] of steps)rows.push(['DEMO-'+(month+1)+'-'+(n+1),'DEMO-A',equipment,step,new Date(start+offset*60000).toISOString().replace('Z',''),new Date(start+(offset+duration)*60000).toISOString().replace('Z',''),lossType?'Recorded staffing wait':'',lossType?'Synthetic recorded reason':'',target,lossType]);}const table={headers,rows,sourceHeaderRow:1,sourceHasHeader:true};return [{id:'batch-demo',name:'batch-synthetic.xlsx',sheet:'Process steps',isDemo:true,date1904:false,table,mapping:WF.suggest('batch',table)}];}
function batchStatsTable(groups,filtered=false,s=wfState('batch').settings){return [[wt('product'),wt('equipment'),groups.some(g=>g.stepSignature)?bt('stepStructure'):wt('step'),bt('timeBasis'),...batchMetrics.map(batchMetricName),wt('status'),filtered?wt('excluded'):bt('iqrCandidates')],...groups.map(g=>{const stats=filtered?g.withoutOutliers:g.all;return [g.product,g.equipment,g.stepSignature?batchStructure(g):g.step,batchClock(g.clock),...batchMetrics.map(k=>batchValue(stats?.[k],k,s)),bt(stats?.status||'insufficient'),g.excludedIds?.length||0];})];}
function batchIssues(w){const seen=new Set();return [...(w.result.normalized?.issues||[]),...(w.result.issues||[])].filter(i=>{const key=JSON.stringify([typeof i==='string'?i:i.code,i.params||[],i.recordId||'',i.sourceId||'',i.file||i.sourceName||'',i.sheet||'',i.row??i.sourceRow??'',i.batchKey||'',i.groupKey||'']);if(seen.has(key))return false;seen.add(key);return true;});}
function batchStructure(g){try{return JSON.parse(g.stepSignature).map(([key,n])=>{const [equipment,step]=JSON.parse(key);return `${step} (${equipment||'—'}) × ${n}`;}).join(' / ');}catch{return '';}}
function batchGroupLabel(g,index=0){return batchLabel(g)+(g.stepSignature?' · '+bt('stepStructure')+' '+(index+1):'');}
function batchCompactStats(groups,filtered=false,s=wfState('batch').settings){return [[wt('name'),wt('n'),wt('mean'),'P50','P90','P95',wt('status')],...groups.map((g,i)=>{const d=filtered?g.withoutOutliers:g.all;return [batchGroupLabel(g,i),d.n,...['mean','p50','p90','p95'].map(k=>batchValue(d[k],k,s)),bt(d.status)];})];}
function batchTimeline(batches,s=wfState('batch').settings,idPrefix='batch-timeline'){
 const colors=['#2a8176','#356d9a','#96702c','#75689a','#4c8651','#945954'],stepColors=new Map([...new Set(batches.flatMap(b=>b.records.map(r=>r.step)))].sort().map((step,i)=>[step,colors[i%colors.length]]));
 const windows=batches.slice(0,20).map(b=>{const valid=b.records.filter(r=>Number.isFinite(r.start)&&Number.isFinite(r.end)&&r.end>r.start&&Number.isFinite(r.duration)&&!r.errors?.length&&r.clock===b.clock).sort((a,c)=>a.start-c.start||a.end-c.end);if(!b.clock||!valid.length)return {b,valid:[],start:null,end:null};return {b,valid,start:b.complete&&Number.isFinite(b.start)?b.start:Math.min(...valid.map(r=>r.start)),end:b.complete&&Number.isFinite(b.end)?b.end:Math.max(...valid.map(r=>r.end))};});
 const max=Math.max(1,...windows.filter(w=>w.start!==null).map(w=>(w.end-w.start)/60000));
 const html=windows.map(({b,valid,start,end},batchIndex)=>{
  const heading=`<h3>${esc([b.product,b.batch].filter(Boolean).join(' / '))}</h3>`;
  if(start===null||end===null)return `<div class="wf-batch-timeline">${heading}${reportText(bt('timelineUnavailable'))}${reportText(bt('incompleteBatch'))}</div>`;
  const lanes=[],p=24,plot=652,x=ms=>p+(ms-start)/60000/max*plot,records=valid.slice(0,200);
  const pieces=records.map((r,i)=>{let lane=lanes.findIndex(until=>until<=r.start);if(lane<0)lane=lanes.length;lanes[lane]=r.end;const left=x(r.start),width=Math.max(.7,x(r.end)-left),top=lane*26+25,color=stepColors.get(r.step),id=idPrefix+'-'+batchIndex+'-'+i,label=`${r.step} · ${r.equipment} · ${fmt(batchValue(r.duration,'duration',s))} ${wt(s.displayUnit)} · ${batchStamp(r.start,r.clock)} → ${batchStamp(r.end,r.clock)}`;return `<g tabindex="0" role="img" aria-label="${esc(label)}"><title>${esc(label)}</title><rect x="${left}" y="${top}" width="${width}" height="22" rx="3" fill="${color}"/><clipPath id="${id}"><rect x="${left+2}" y="${top}" width="${Math.max(0,width-4)}" height="22"/></clipPath>${width>28?`<text x="${left+3}" y="${top+15}" clip-path="url(#${id})" style="fill:white;font-size:10px">${esc(r.step)}</text>`:''}</g>`;}).join('');
  const height=Math.max(78,lanes.length*26+54),laneHeight=Math.max(22,lanes.length*26),gaps=b.complete?b.gaps||[]:[];
  const gapRects=gaps.map(g=>`<rect x="${x(g.start)}" y="25" width="${Math.max(0,x(g.end)-x(g.start))}" height="${laneHeight}" fill="#d7dfe7"><title>${esc(wt('gaps'))}: ${fmt(batchValue(g.duration,'duration',s))} ${esc(wt(s.displayUnit))}</title></rect>`).join('');
  const svg=chartBase(700,height,`<title>${esc(batchLabel(b))}</title><text x="${p}" y="15" style="font-size:10px">${esc(batchStamp(start,b.clock))}</text><rect x="${p}" y="25" width="${Math.max(0,x(end)-p)}" height="${laneHeight}" fill="#fafbfc" stroke="#d7dfe7"/>${gapRects}${pieces}<text x="${p}" y="${height-5}" style="font-size:10px">0</text><text x="${p+plot}" y="${height-5}" text-anchor="end" style="font-size:10px">${fmt(batchValue(max,'duration',s),1)} ${esc(wt(s.displayUnit))}</text>`,batchLabel(b));
  return `<div class="wf-batch-timeline" style="break-inside:avoid">${heading}${svg}${!b.complete?reportText(bt('observedTimeline')):''}${valid.length>200?reportText(wt('reportLimit',[200,valid.length])):''}</div>`;
 }).join('');return html+(batches.length>20?reportText(wt('reportLimit',[20,batches.length])):'');
}
function batchTrend(batches,s=wfState('batch').settings){const list=batches.filter(b=>Number.isFinite(b.elapsed)).sort((a,b)=>a.start-b.start).slice(0,500);if(!list.length)return reportText(wt('noData'));const max=Math.max(1,...list.map(b=>b.elapsed)),x=i=>50+(list.length===1?0:i/(list.length-1)*600),y=v=>190-v/max*160;const points=list.map((b,i)=>`${x(i)},${y(b.elapsed)}`).join(' ');return chartBase(700,220,`<line x1="50" x2="650" y1="190" y2="190" stroke="#aab9c7"/><polyline points="${points}" fill="none" stroke="#2a8176" stroke-width="2"/>${list.map((b,i)=>`<circle cx="${x(i)}" cy="${y(b.elapsed)}" r="3" fill="#2a8176"><title>${esc(b.batch)}: ${fmt(batchValue(b.elapsed,'duration',s))} ${esc(wt(s.displayUnit))}</title></circle>`).join('')}<text x="4" y="30" font-size="10">${fmt(batchValue(max,'duration',s),1)}</text><text x="50" y="212" font-size="10">${esc(list[0].batch)}</text><text x="570" y="212" font-size="10">${esc(list.at(-1).batch)}</text>`,wt('batchElapsed')+' · '+wt(s.displayUnit))+(batches.length>500?reportText(wt('reportLimit',[500,batches.length])):'');}
function batchTable(r,s){return [[wt('product'),wt('batch'),wt('equipment'),wt('batchElapsed'),wt('stepSum'),wt('active'),wt('gaps'),wt('status')],...r.batches.map(b=>[b.product,b.batch,b.equipmentSet.join(' / '),...['elapsed','stepTotal','active','gap'].map(k=>batchValue(b[k],k,s)),b.complete?(b.partial?bt('partialSelection'):bt('complete')):bt('incompleteBatch')])];}
function batchComparisonTable(r,s){return [[wt('product'),wt('equipment'),wt('step'),bt('timeBasis'),bt('stepStructure'),wt('name'),wt('current'),wt('previous'),wt('change'),wt('relative')],...(r.comparisons||[]).flatMap(c=>{let structure='';if(c.kind==='batch'){try{structure=batchStructure({stepSignature:JSON.parse(c.key)[3]});}catch{}}return ['n','mean','median','sd','p90','p95'].map(k=>[c.product,c.equipment,c.kind==='batch'?wt('batchElapsed'):c.step,batchClock(c.clock),structure,batchMetricName(k),batchValue(c.current[k],k,s),batchValue(c.previous[k],k,s),batchValue(c.deltas[k]?.absolute,k,s),c.deltas[k]?.relative??null]);})];}
function batchIssueTable(issues,records=[]){const byId=new Map(records.map(r=>[r.id,r]));return [[wt('source'),wt('row'),wt('batch')+' / '+wt('step'),wt('start')+' / '+wt('end'),wt('issue')],...issues.map(i=>{const r=byId.get(i.recordId);return [[i.sourceName||i.file||'',i.sheet||''].filter(Boolean).join(' / '),i.sourceRow??i.row??'',r?[r.batch,r.step].filter(Boolean).join(' / '):'',r?String(r.rawStart??'')+' → '+String(r.rawEnd??''):'',batchReason(i)];})];}
function batchParetoResult(r,s){return {...r,total:s.paretoMetric==='count'?r.total:batchValue(r.total,'duration',s),items:r.items.map(x=>({...x,value:s.paretoMetric==='count'?x.value:batchValue(x.value,'duration',s)}))};}
function batchLossTable(r,s){return [[wt('name'),wt(s.displayUnit)],...['waiting','downtime','processDelay','excess','gap'].map(k=>[wt(k==='processDelay'?'delay':k==='gap'?'gaps':k),batchValue(r.timeLoss[k],k,s)])];}
function batchDistributionSection(groups,s,report=false){
 const all=batchCompactStats(groups,false,s),filtered=batchCompactStats(groups,true,s);
 const details=report?groups.slice(0,300).map((g,i)=>{const values=keys=>reportTable(keys.map(batchMetricName),[keys.map(k=>batchValue(g.all[k],k,s))]);const body=s.outlier==='iqr'?reportTable([wt('name'),wt('includeAll'),wt('filtered')],batchMetrics.map(k=>[batchMetricName(k),batchValue(g.all[k],k,s),batchValue(g.withoutOutliers[k],k,s)])):values(['n','mean','median','sd','p50'])+values(['p75','p90','p95','min','max']);return `<div style="break-inside:avoid">${reportSection(batchGroupLabel(g,i),(g.stepSignature?reportText(bt('stepStructure')+': '+batchStructure(g)):'')+body+reportText(bt(g.all.status)))}</div>`;}).join(''):`<details><summary>${esc(wt('normalizedData'))}</summary>${tableSection(wt('includeAll'),batchStatsTable(groups,false,s),300)}${s.outlier==='iqr'?tableSection(wt('filtered'),batchStatsTable(groups,true,s),300):''}</details>`;

 return tableSection(wt('includeAll'),all,300)+(s.outlier==='iqr'?tableSection(wt('filtered'),filtered,300):'')+details+(report&&groups.length>300?reportText(wt('reportLimit',[300,groups.length])):'');
}
function batchComparisonSection(r,s,report=false){return (r.comparisons||[]).slice(0,100).map(c=>{const current={...c.current,mean:batchValue(c.current.mean,'mean',s)},previous={...c.previous,mean:batchValue(c.previous.mean,'mean',s)},delta={...c.deltas.mean,absolute:batchValue(c.deltas.mean.absolute,'mean',s)},label=batchLabel(c)+(c.kind==='batch'?' · '+wt('batchElapsed'):'');const visual=recurringComparisonBar({current,previous,deltas:{mean:delta}},label);let structure='';if(c.kind==='batch'){try{structure=batchStructure({stepSignature:JSON.parse(c.key)[3]});}catch{}}return `<div style="break-inside:avoid">${reportSection(label,(structure?reportText(bt('stepStructure')+': '+structure):'')+`<div style="max-width:230px">${visual}</div>`+reportTable([wt('name'),wt('previous'),wt('current'),wt('change'),wt('relative')],['n','mean','median','sd','p90','p95'].map(k=>[batchMetricName(k),batchValue(c.previous[k],k,s),batchValue(c.current[k],k,s),batchValue(c.deltas[k]?.absolute,k,s),c.deltas[k]?.relative??null])))}</div>`;}).join('')+((r.comparisons||[]).length>100?reportText(wt('reportLimit',[100,r.comparisons.length])):'');}
function batchIqrBatches(r,s){return [[wt('product'),wt('batch'),wt('equipment'),wt('batchElapsed'),bt('lowerFence'),bt('upperFence')],...r.batchGroups.flatMap(g=>{const excluded=new Set(g.excludedIds);return g.batches.filter(b=>excluded.has(b.id)).map(b=>[b.product,b.batch,b.equipmentSet.join(' / '),batchValue(b.elapsed,'duration',s),batchValue(g.fences.lower,'duration',s),batchValue(g.fences.upper,'duration',s)]);})];}
function renderBatchResults(w){const r=w.result,s=w.settings,issues=batchIssues(w),candidates=batchIqrBatches(r,s);return `<section class="panel"><h2>${esc(wt('stepStats'))} · ${esc(wt(s.displayUnit))}</h2><p class="section-note">${esc(bt('viewMethod'))}</p>${batchDistributionSection(r.groups,s)}<details><summary>${esc(bt('iqrCandidates'))} (${r.excludedRows.length})</summary>${reportTable([wt('source'),wt('row'),wt('batch'),wt('step'),wt('duration'),bt('lowerFence'),bt('upperFence')],r.excludedRows.slice(0,300).map(x=>[x.sourceName,x.sourceRow,x.batch,x.step,batchValue(x.duration,'duration',s),batchValue(x.lower,'duration',s),batchValue(x.upper,'duration',s)]))}</details></section><section class="panel"><h2>${esc(bt('batchDistribution'))} · ${esc(wt(s.displayUnit))}</h2>${reportText(bt('batchDistributionHelp'))}${batchDistributionSection(r.batchGroups,s)}${candidates.length>1?`<details><summary>${esc(bt('iqrCandidates'))}</summary>${tableSection(bt('batchDistribution'),candidates,300)}</details>`:''}</section><section class="panel"><h2>${esc(wt('batchStats'))} · ${esc(wt(s.displayUnit))}</h2>${batchTrend(r.batches,s)}${tableSection(wt('batchStats'),batchTable(r,s),300)}</section><section class="panel"><h2>${esc(wt('timeline'))}</h2><p class="section-note">${esc(bt('timelineHelp'))}</p>${batchTimeline(r.batches,s)}</section><section class="panel"><h2>${esc(wt('timeLoss'))} · ${esc(wt(s.displayUnit))}</h2>${tableSection(wt('timeLoss'),batchLossTable(r,s))}<p>${esc(bt('targetCoverage',[r.timeLoss.referenceCount,r.timeLoss.unreferencedCount]))}</p><p>${esc(wt(s.reference==='p50'?'p50Reference':'targetReference'))}</p>${r.pareto.result.items.length?paretoChart(batchParetoResult(r.pareto.result,s)):reportText(wt('noData'))}<button id="batch-pareto" ${r.pareto.rows.length?'':'disabled'}>${esc(wt('paretoOpen'))}</button></section><section class="panel"><h2>${esc(wt('beforeAfter'))} · ${esc(wt(s.displayUnit))}</h2>${reportText(wt('noCausality'))}${reportText(wt(s.outlier==='iqr'?'filtered':'includeAll'))}${batchComparisonSection(r,s)}</section><section class="panel"><details><summary>${esc(wt('audit'))} (${issues.length})</summary>${tableSection(wt('audit'),batchIssueTable(issues,r.audit.map(a=>a.record)),300)}</details><details><summary>${esc(wt('method'))}</summary>${reportText(wt('batchMethod'))}${reportText(wt('batchHelp'))}</details></section>`;}
function bindBatchResults(){if($('#batch-pareto'))$('#batch-pareto').onclick=()=>{const w=wfState('batch'),r=w.result,unit=w.settings.paretoMetric==='count'?wt('count'):wt(w.settings.displayUnit);state.paretoData={headers:[wt(w.settings.paretoGroup),wt(w.settings.paretoMetric)+' ('+unit+')'],rows:r.pareto.rows.map(([label,v])=>[label,w.settings.paretoMetric==='count'?v:batchValue(v)]),name:wt('batch.title'),isDemo:w.sources.every(s=>s.isDemo)};state.paretoCategory=0;state.paretoValue=1;state.imports.pareto={workbook:null,raw:null,headerRow:1,hasHeader:true,headerDetection:null,sheet:'',appliedPreset:'',restoreNote:''};navigate('pareto');};}
function buildBatchReport(){const w=wfState('batch'),r=w.result,s=w.settings;if(!r||!r.valid)throw Error(wt('noData'));const title=s.reportTitle||wt('batch.title'),conditions=[[wt('name'),wt('value')],...['product','equipment','batch','step','from','to','previousFrom','previousTo'].map(k=>[wt(k),s[k]||wt('all')]),[wt('displayUnit'),wt(s.displayUnit)],[wt('targetUnit'),wt(s.targetUnit)],[wt('outlier'),wt(s.outlier==='iqr'?'iqr':'includeAll')],[wt('referenceBasis'),wt(s.reference==='p50'?'p50Reference':'targetReference')],[wt('minSamples'),s.minSamples],[wt('paretoMetric'),wt(s.paretoMetric)],[wt('paretoGroup'),wt(s.paretoGroup)],[wt('method'),wt('batchMethod')],[wt('filters'),wt('batchHelp')]];
 const stats=batchStatsTable(r.groups,false,s),filtered=batchStatsTable(r.groups,true,s),batches=batchTable(r,s),loss=batchLossTable(r,s),comparison=batchComparisonTable(r,s),issues=batchIssueTable(batchIssues(w),r.audit.map(a=>a.record)),excluded=[[wt('source'),wt('row'),wt('batch'),wt('step'),wt('duration'),bt('lowerFence'),bt('upperFence')],...r.excludedRows.map(x=>[x.sourceName,x.sourceRow,x.batch,x.step,batchValue(x.duration,'duration',s),batchValue(x.lower,'duration',s),batchValue(x.upper,'duration',s)])];
 const audit=[[wt('source'),wt('sheet'),wt('row'),wt('product'),wt('batch'),wt('equipment'),wt('step'),wt('start'),wt('end'),wt('duration'),wt('target'),wt('lossType'),wt('category'),wt('reason'),wt('current'),wt('previous')],...(r.audit||[]).map(a=>{const x=a.record||a;return [x.sourceName,x.sheet,x.sourceRow,x.product,x.batch,x.equipment,x.step,batchStamp(x.start,x.clock)||x.rawStart,batchStamp(x.end,x.clock)||x.rawEnd,batchValue(x.duration,'duration',s),batchValue(x.target,'duration',s),x.lossType,x.category,x.reason,bt(a.currentStatus||'included'),bt(a.previousStatus||'notRequested')];})];
 const pareto=[[wt(s.paretoGroup),wt(s.paretoMetric), '%',bt('cumulative')],...r.pareto.result.items.map(x=>[x.label,s.paretoMetric==='count'?x.value:batchValue(x.value,'duration',s),x.percent,x.cumulative])];
 const sources=[[wt('source'),wt('sheet'),wt('header'),wt('row')+' / N'],...w.sources.map(x=>[x.name,x.sheet,x.table.sourceHeaderRow||1,x.table.rows.length])];
 const batchAll=batchStatsTable(r.batchGroups,false,s),batchFiltered=batchStatsTable(r.batchGroups,true,s),batchCandidates=batchIqrBatches(r,s);
 conditions.push([wt('normalizedData')+' / N',r.counts.records],[wt('duration')+' / N',r.counts.currentValid],[wt('excluded'),r.counts.currentExcluded],[wt('batchStats')+' / N',r.counts.currentBatches],[bt('complete')+' / N',r.counts.completeBatches],[bt('iqrCandidates'),r.excludedRows.length]);
 const html=`<h1>${esc(title)}</h1><p class="report-meta">Manufacturing Toolbox · ${esc(new Date().toISOString())}</p>`+tableSection(wt('conditions'),conditions)+tableSection(wt('source'),sources)+reportText(bt('viewMethod'))+reportSection(wt('stepStats')+' · '+wt(s.displayUnit),batchDistributionSection(r.groups,s,true))+reportSection(bt('batchDistribution')+' · '+wt(s.displayUnit),reportText(bt('batchDistributionHelp'))+batchDistributionSection(r.batchGroups,s,true))+reportSection(wt('batchStats')+' · '+wt(s.displayUnit),batchTrend(r.batches,s))+tableSection(wt('batchStats'),batches,300)+reportSection(wt('timeline'),reportText(bt('timelineHelp'))+batchTimeline(r.batches,s,'batch-report-timeline'))+tableSection(wt('timeLoss'),loss)+reportText(bt('targetCoverage',[r.timeLoss.referenceCount,r.timeLoss.unreferencedCount]))+reportSection(wt('paretoMetric'),r.pareto.result.items.length?paretoChart(batchParetoResult(r.pareto.result,s)):reportText(wt('noData')))+tableSection(wt('paretoMetric'),pareto,100)+reportSection(wt('beforeAfter')+' · '+wt(s.displayUnit),reportText(wt('noCausality'))+reportText(wt(s.outlier==='iqr'?'filtered':'includeAll'))+batchComparisonSection(r,s,true))+tableSection(wt('audit'),issues,300)+tableSection(bt('iqrCandidates'),excluded,300)+tableSection(bt('batchDistribution')+' · '+bt('iqrCandidates'),batchCandidates,300)+reportText(wt('reportNote'));
 const sheets=[[wt('conditions'),conditions],[wt('source'),sources],[wt('stepStats'),stats],[wt('filtered'),filtered],[wt('batchStats'),batches],[bt('batchDistribution'),batchAll],[bt('batchDistribution')+' IQR',batchFiltered],[bt('batchDistribution')+' '+bt('iqrCandidates'),batchCandidates],[wt('timeLoss'),loss],[wt('paretoMetric'),pareto],[wt('beforeAfter'),comparison],[wt('audit'),audit],[wt('issue'),issues],[bt('iqrCandidates'),excluded],...w.sources.map((x,i)=>[wt('source')+' '+(i+1),[x.table.headers,...x.table.rows]])].map(([name,rows],i)=>[name.replace(/[\\/?*\[\]:]/g,' ').slice(0,26)+' '+(i+1),rows]);return {title,filename:title+'.xlsx',sheets,html};}
